// Lembrete de Aula - 1 hora antes
const FALLBACK_AULA = 'Olá, {{nomeCliente}}!\n\nLembrete: sua aula de {{descricaoAula}} começa em 1 hora! 🕐\n\n⏰ Horário: {{horarioAula}}\n📍 Local: {{nomeEmpresa}}\n\nAté já! 💪';

const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;

  let mensagem = data.template_mensagem;
  if (!mensagem || mensagem.trim() === '') {
    mensagem = FALLBACK_AULA;
  }

  const horarioFormatado = data.horario ? data.horario.substring(0, 5) : '';

  const variaveis = {
    '{{nomeCliente}}': data.nome_cliente || 'Aluno',
    '{{descricaoAula}}': data.descricao || 'aula',
    '{{horarioAula}}': horarioFormatado,
    '{{nomeEmpresa}}': data.nome_empresa || 'Equipe'
  };

  Object.entries(variaveis).forEach(([chave, valor]) => {
    mensagem = mensagem.replace(new RegExp(chave, 'g'), valor);
  });

  let telefone = String(data.telefone || '').replace(/\D/g, '');
  if (!telefone.startsWith('55')) telefone = '55' + telefone;

  results.push({
    json: {
      ...data,
      mensagem,
      telefone,
      evolution_url: `${data.evolution_api_url}/message/sendText/${data.evolution_instance_name}`,
      tipo_lembrete: 'lembrete_aula'
    }
  });
}

return results;

