// Normaliza o erro ANTES de gravar o log. Sem isto o registro nasce com
// "Erro no envio" e erro_codigo null — foi o que jogou 46% das falhas de
// cobranca na classe 'indeterminada'.
// pairedItem preservado p/ $('2. Criar Msg Aula').item continuar resolvendo.
const items = $input.all();

return items.map((item, i) => {
  const j = item.json || {};
  const err = j.error || {};
  const status = err.status ?? err.statusCode ?? j.statusCode ?? null;
  const corpo = err.response?.body ?? err.body ?? err.message ?? j.message ?? null;
  const texto = typeof corpo === 'string' ? corpo : JSON.stringify(corpo ?? null);

  let codigo = status ? `http_${status}` : 'exception';
  if (status === 500) codigo = 'instance_500';
  else if (status === 404) codigo = 'instance_not_found';
  else if (status === 401 || status === 403) codigo = 'auth_failed';
  else if (status === 400) codigo = 'bad_request';
  if (/exists"?\s*:\s*false/i.test(texto || '')) codigo = 'numero_inexistente';
  if (/Connection Closed/i.test(texto || '')) codigo = 'connection_closed';

  return {
    json: { erro_codigo: codigo, http_status: status,
      erro_mensagem: texto && texto !== 'null' ? texto
        : 'Falha no envio do lembrete (provedor nao detalhou)' },
    pairedItem: item.pairedItem ?? { item: i }
  };
});
